#define main existing_main
#include "simt_prefill.cu"
#undef main
namespace mellum16 {namespace {
template<class F> float AttentionTime(F launch){for(int i=0;i<10;++i)launch();Check(cudaDeviceSynchronize());cudaEvent_t a,b;Check(cudaEventCreate(&a));Check(cudaEventCreate(&b));Check(cudaEventRecord(a));for(int i=0;i<30;++i)launch();Check(cudaEventRecord(b));Check(cudaEventSynchronize(b));float ms=0;Check(cudaEventElapsedTime(&ms,a,b));cudaEventDestroy(a);cudaEventDestroy(b);return ms/30;}
void Benchmark(int context,bool local){
  const int capacity=local?1024:8192;std::vector<float> q(4096);std::vector<__nv_bfloat16> k(capacity*512),v(k);
  for(int i=0;i<4096;++i)q[i]=__bfloat162float(__float2bfloat16_rn(std::sin(float(i))));for(int row=0;row<capacity;++row)for(int d=0;d<512;++d){k[row*512+d]=__float2bfloat16_rn(std::cos(float(row*7+d)));v[row*512+d]=__float2bfloat16_rn(std::sin(float(row*5+d)));}
  Buffer query(q.size()*4),keys(k.size()*2),values(v.size()*2),a(4096*4),b(4096*4),workspace(capacity*32*4),command(sizeof(SimtCommand)),bad(4);Check(cudaMemcpy(query.p,q.data(),query.bytes,cudaMemcpyHostToDevice));Check(cudaMemcpy(keys.p,k.data(),keys.bytes,cudaMemcpyHostToDevice));Check(cudaMemcpy(values.p,v.data(),values.bytes,cudaMemcpyHostToDevice));Check(cudaMemset(bad.p,0,4));SetSimtCommand<<<1,1>>>(command.As<SimtCommand>(),0,context-1);
  auto old=[&]{if(local)AttendSimt<true,1,false><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),a.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());else AttendSimt<false,1,false><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),a.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());};
  auto opt=[&]{simt_attention_split::Launch(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),command.As<SimtCommand>(),capacity,local,workspace.As<float>(),bad.As<int>(),nullptr,context<=4096?4096:8192);};
  auto prefetched=[&]{if(local)AttendSimt<true,8><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());else AttendSimt<false,8><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());};
  auto address=[&]{if(local)AttendSimt<true><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());else AttendSimt<false><<<32,256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),command.As<SimtCommand>(),capacity,workspace.As<float>(),bad.As<int>());};
  old();opt();Check(cudaDeviceSynchronize());std::vector<float> x(4096),y(x);Check(cudaMemcpy(x.data(),a.p,a.bytes,cudaMemcpyDeviceToHost));Check(cudaMemcpy(y.data(),b.p,b.bytes,cudaMemcpyDeviceToHost));Require(!memcmp(x.data(),y.data(),a.bytes),"attention benchmark reference mismatch");
  address();Check(cudaDeviceSynchronize());Check(cudaMemcpy(y.data(),b.p,b.bytes,cudaMemcpyDeviceToHost));Require(!memcmp(x.data(),y.data(),a.bytes),"address attention benchmark reference mismatch");
  prefetched();Check(cudaDeviceSynchronize());Check(cudaMemcpy(y.data(),b.p,b.bytes,cudaMemcpyDeviceToHost));Require(!memcmp(x.data(),y.data(),a.bytes),"prefetched attention benchmark reference mismatch");
  for(int rep=0;rep<5;++rep){float before,after;if(rep%2){after=AttentionTime(opt);before=AttentionTime(old);}else{before=AttentionTime(old);after=AttentionTime(opt);}std::cout<<"context="<<context<<" local="<<local<<" rep="<<rep<<" original_ms="<<before<<" split_ms="<<after<<" address_ms="<<AttentionTime(address)<<" prefetch_ms="<<AttentionTime(prefetched)<<" speedup="<<before/after<<'\n';}
}
void BatchBenchmark(int context,bool local){
  const int capacity=local?1024:8192,rows=8,base=context-rows;
  std::vector<float> q(rows*4096);std::vector<__nv_bfloat16> k(capacity*512),v(k),current(256*1024);
  for(int i=0;i<rows*4096;++i)q[i]=__bfloat162float(__float2bfloat16_rn(std::sin(float(i))));
  for(int pos=std::max(0,base-capacity);pos<context;++pos)for(int d=0;d<512;++d){k[(pos%capacity)*512+d]=Value(pos,d,true);v[(pos%capacity)*512+d]=Value(pos,d,false);if(pos>=base){current[(pos-base)*512+d]=Value(pos,d,true);current[(256+pos-base)*512+d]=Value(pos,d,false);}}
  Buffer query(q.size()*4),keys(k.size()*2),values(v.size()*2),stage(current.size()*2),a(q.size()*4),b(q.size()*4),workspace(8ULL*32*8192*4),state(sizeof(SimtBatch)),bad(4);
  Check(cudaMemcpy(query.p,q.data(),query.bytes,cudaMemcpyHostToDevice));Check(cudaMemcpy(keys.p,k.data(),keys.bytes,cudaMemcpyHostToDevice));Check(cudaMemcpy(values.p,v.data(),values.bytes,cudaMemcpyHostToDevice));Check(cudaMemcpy(stage.p,current.data(),stage.bytes,cudaMemcpyHostToDevice));Check(cudaMemset(bad.p,0,4));SetSimtBatch<<<1,1>>>(state.As<SimtBatch>(),base,rows,8192,bad.As<int>());
  auto launch=[&]<bool Fast,int Prefetch>(float* output){if(local)AttendSimtBatch<true,Fast,Prefetch><<<dim3(32,8),256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),output,state.As<SimtBatch>(),capacity,workspace.As<float>(),bad.As<int>(),stage.As<__nv_bfloat16>(),0);else AttendSimtBatch<false,Fast,Prefetch><<<dim3(32,8),256>>>(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),output,state.As<SimtBatch>(),capacity,workspace.As<float>(),bad.As<int>(),stage.As<__nv_bfloat16>(),0);};
  auto old=[&]{launch.template operator()<false,1>(a.As<float>());};auto address=[&]{launch.template operator()<true,1>(b.As<float>());};auto prefetch=[&]{launch.template operator()<true,8>(b.As<float>());};
  auto split=[&]{simt_prefill_attention_split::Launch(query.As<float>(),keys.As<__nv_bfloat16>(),values.As<__nv_bfloat16>(),b.As<float>(),state.As<SimtBatch>(),capacity,local,workspace.As<float>(),bad.As<int>(),stage.As<__nv_bfloat16>(),0,nullptr);};
  old();Check(cudaDeviceSynchronize());std::vector<float> x(q.size()),y(x);Check(cudaMemcpy(x.data(),a.p,a.bytes,cudaMemcpyDeviceToHost));
  const auto verify=[&](auto candidate){candidate();Check(cudaDeviceSynchronize());Check(cudaMemcpy(y.data(),b.p,b.bytes,cudaMemcpyDeviceToHost));Require(!memcmp(x.data(),y.data(),a.bytes),"batch attention performance candidate changed arithmetic");};verify(address);verify(prefetch);verify(split);
  for(int rep=0;rep<5;++rep){const float original=AttentionTime(old),direct=AttentionTime(address),prefetched=AttentionTime(prefetch),tiled=AttentionTime(split);std::cout<<"batch_rows="<<rows<<" context="<<context<<" local="<<local<<" rep="<<rep<<" original_ms="<<original<<" address_ms="<<direct<<" prefetch_ms="<<prefetched<<" split_ms="<<tiled<<'\n';}
}
}}
int main(){try{for(int context:{128,1024,2000,4000,8000})for(bool local:{false,true}){mellum16::Benchmark(context,local);mellum16::BatchBenchmark(context,local);}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
